"""Render the measured codec/vocabulary study; do not imply a training-quality gain."""
import argparse
import json
from pathlib import Path


def main():
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);a=p.parse_args();root=a.root.resolve()
    out=root/'codec-study';s=json.loads((out/'summary.json').read_text());b=json.loads((out/'head-benchmark.json').read_text())
    dev=s['metrics']['development'];train=s['metrics']['training_inventory'];here=Path(__file__).resolve().parent
    lines=['# Выходной словарь и кодирование МК-61','',
      '**Для машинного вывода не требуется вычислять все 8192 логита.** Для текущего формата программ, арифметических `<calc>` и инструментальных ответов построен набор из 54 BPE-токенов; для канонического HEX и инструментов без формулы — 37. Он включает представление всех 256 байтов, а не только встретившихся команд. Свободное русское объяснение в этот набор не входит.','',
      'У обеих моделей входная таблица и выходная проекция связаны (`tie_word_embeddings=true`). У 3M это одна матрица 8192 × 128 = 1 048 576 параметров из 3 017 984, то есть 34,7%. Называть её отдельным избыточным выходным слоем было неточно: она также кодирует русский вход. Отбор строк при выводе сохраняет всю таблицу входа и не уменьшает число весов.','',
      '| Модель | Полная проекция, ток/с | 54 строки, ток/с | Ускорение | Совпадение генераций |','| --- | ---: | ---: | ---: | ---: |']
    labels={'small':'3,02M Q4','champion':'5,79M Q4'}
    for arm,x in b['models'].items():
        m=x['measurements'];lines.append(f"| {labels[arm]} | {m['full8192']['decode_tokens_per_second_median']:.1f} | {m['selected']['decode_tokens_per_second_median']:.1f} | {x['decode_speed_ratio']:.3f}× | {x['identical_greedy_generations']}/{x['generation_probes']} |")
    lines+=['','Это замер одного и того же Q4 LUT-ядра на хосте: одинаковые 512 входных токенов, затем одинаковая последовательность 32 токенов; медиана трёх измерений после прогрева. Сами 54 логита совпали с полным расчётом точно на 23 позициях у каждой модели. Prefill практически не изменился. Изменена только исследовательская копия сохранённых C++-исходников; рабочие исходники другого агента и веса моделей не изменялись. PicoCalc/RP2350 не измерялся.','',
      '`60 61 10 50` сейчас имеет 11 токенов: две цифры на байт и отдельные пробелы. Специальные байтовые токены могли бы представлять эту программу четырьмя токенами. Здесь каждый байт остаётся байтом, включая операнды и адреса; таблица не составляет программу за нейросеть.','',
      f"Частоты построены только на инвентаре {train['programs']:,} учебных программ. В него входят по одной цели на естественно-языковое условие, формальные цели и сохранённая обратная связь. Это не фактическое взвешенное распределение выборки SGD. Для редких и отсутствующих байтов добавлена псевдочастота 1, поэтому все 256 значений доступны. На открытой валидации — {dev['programs']} программ и {dev['program_bytes']:,} байта.",'',
      '| Представление тела программы | Токенов на байт: обучение | Валидация |','| --- | ---: | ---: |',
      f"| Текущий HEX через BPE | {train['hex_body_tokens_per_byte']:.4f} | {dev['hex_body_tokens_per_byte']:.4f} |"]
    for radix in [2,16,32,64,256]:
        lines.append(f"| Префиксный код, алфавит {radix} токенов | {train['codes'][str(radix)]['symbols_per_byte']:.4f} | {dev['codes'][str(radix)]['symbols_per_byte']:.4f} |")
    lines+=['',
      f"Алфавит Хаффмана из 32 токенов сокращает тело программы на {100*dev['codes']['32']['body_reduction_vs_hex']:.1f}%. Если сохранить нынешние BPE-маркеры и промежуточную формулу, весь ответ сокращается на {100*(1-dev['codes']['32']['full_answer_tokens_with_existing_markers']/dev['full_answer_tokens']):.1f}%. Следовательно, экономию на теле программы нельзя автоматически переносить на всю генерацию. Отдельные токены для `<write>`, `<run/>` и других маркеров тоже можно изучить, но здесь их эффект не измерен.",'',
      'С одним новым токеном на символ алфавит из 32 элементов добавляет 2 304 байта Q4-весов у 3M и 4 608 у чемпиона. Прямой код из 256 байтовых токенов добавляет соответственно 18 432 и 36 864 байта. Это расчёт связанной матрицы с группами 32 и FP16-масштабами, без файлов токенизатора и таблиц декодирования. Последний вариант проще декодировать; частотный вариант почти такой же короткий на текущем курсе и требует меньше новых строк.','',
      f"Проверены все 256 байтов и случайные программы длиной до 105 байтов. Некорректные и незавершённые префиксы отвергаются. На {s['emulator_roundtrips']} дополнительных прогонах настоящего ядра МК-61 кодирование и декодирование сохранили все результаты. Это проверка обратимости; новые кодировки ещё не использовались при обучении модели.",'',
      '| Входной словарь | Параметров у прежней 3M после обрезки | Экономия Q4-весов | Рост числа входных токенов |','| --- | ---: | ---: | ---: |',
      '| 8192 | 3 017 984 | — | — |']
    for size in [4096,2048,1024]:
        x=s['pruned_vocabulary'][str(size)];lines.append(f"| {size} | {x['parameters_small']:,} | {x['q4_weight_bytes_saved_small']/2**20:.3f} МиБ | +{100*(x['input_inflation']-1):.1f}% |")
    lines+=['',
      'Обрезка сохраняет первые правила исходного BPE вместе со всеми зависимостями и базовыми байтами. На 380 проверочных русских условиях подтверждено точное восстановление текста. Но понимание текста и качество программ после смены сегментации не измерялись: существующая модель не была переобучена с меньшим словарём. Расчёт экономии не включает уменьшение файлов токенизатора.','',
      '**Практический порядок:** сначала малый выход при прежнем русском входе; затем сравнение HEX и новых кодовых токенов при одинаковых исходных весах, данных и числе обновлений. Уменьшение входного словаря — отдельный опыт: он меняет сегментацию русского и фактическую вместимость контекста.','',
      '**Улучшение качества от нового кодирования пока не доказано.** В прежней диагностике обе модели правильно переводили свои собственные формулы в HEX на всех 84 составных условиях, включая неверные формулы. Новые токены могут снизить ошибки сериализации и изменить обучение, но устранение ошибок понимания требует отдельного сравнения.','',
      f"[Измерения и частоты]({out}/summary.json) · [Замер малого выхода]({out}/head-benchmark.json) · [Таблица Хаффмана-32]({out}/codebook-32.json) · [Прототип кодека]({here}/byte_codec.py)",'']
    (here/'CODEC_STUDY.md').write_text('\n'.join(lines))
    final=here/'FINAL_RESULTS.md';marker='<!-- codec-study -->'
    previous=final.read_text().split(marker)[0].rstrip()
    final.write_text(previous+'\n\n'+marker+'\n\n## Выходной словарь и кодек\n\nНа сохранённом нативном ядре проверена проекция 54 строк вместо 8192: около 1,28× у 3M и 1,30× у чемпиона, без изменения весов и с совпадением12/12 проверочных генераций. Частотное кодирование32 токенами близко к одному токену на байт. Новое кодирование ещё не обучалось; прирост качества не установлен. [Измерения и ограничения](CODEC_STUDY.md).\n')
    state_path=here/'work-state.json';state=json.loads(state_path.read_text())
    state['codec_vocabulary_study']={'complete':True,'report':str(here/'CODEC_STUDY.md'),'output_tokens_tested':54,
      'input_vocabulary_kept':8192,'new_codec_quality_measured':False,'new_codec_training_started':False,
      'primary_model_weights_modified':False,'product_sources_modified':False,
      'head_decode_speed_ratio':{arm:x['decode_speed_ratio']for arm,x in b['models'].items()},
      'greedy_generations_unchanged':sum(x['identical_greedy_generations']for x in b['models'].values()),
      'huffman32_symbols_per_byte_on_development':dev['codes']['32']['symbols_per_byte'],
      'codec_unit_tests_passed':3,'emulator_roundtrips':s['emulator_roundtrips']}
    state_path.write_text(json.dumps(state,ensure_ascii=False,indent=2)+'\n')
    print(here/'CODEC_STUDY.md')


if __name__=='__main__':main()
